"#!/usr/bin/env bash
# Diagnostic probe #2: docker runtime, running stack, port bindings. Read-only.\nset -u\necho \"=== DOCKER CONTEXT ===\"\ndocker context ls 2>&1\necho\necho \"=== DOCKER INFO (kernel/os) ===\"\ndocker info --format '{{.OperatingSystem}} | {{.KernelVersion}} | {{.Name}} | {{.Driver}}' 2>&1\necho\necho \"=== DOCKER PS ===\"\ndocker ps -a --format 'table {{.Names}}\\t{{.Image}}\\t{{.Status}}\\t{{.Ports}}' 2>&1\necho\necho \"=== WIN LISTENING PORTS ===\"\nnetstat.exe -ano 2>/dev/null | grep LISTENING | grep -E ':(80|443|1883|8080|8082|9001)[[:space:]]' 2>/dev/null\necho\necho \"=== WSL LISTENING ===\"\nss -tlnp 2>/dev/null\necho\necho \"=== HOST IP FOR LAN ===\"\nip -4 addr show eth0 2>/dev/null | grep -oP 'inet \\K[\\d.]+'\n/mnt/c/Windows/System32/ipconfig.exe 2>/dev/null | grep -A5 -i 'wireless\\|ethernet adapter' | grep -i 'IPv4' | head -5\necho\necho \"=== FIREWALL PROFILE ===\"\n/mnt/c/Windows/System32/netsh.exe advfirewall show allprofiles state 2>/dev/null | head -20"